-- create "media_uploads" table
CREATE TABLE "media_uploads" ("id" uuid NOT NULL, "object_key" character varying(255) NOT NULL, "content_type" character varying(50) NOT NULL, "size_bytes" bigint NOT NULL, "purpose" character varying(20) NOT NULL, "created_by" bigint NOT NULL, "created_at" timestamptz NOT NULL, "expires_at" timestamptz NOT NULL, "consumed_at" timestamptz NULL, "shop_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "media_uploads_shops_shop" FOREIGN KEY ("shop_id") REFERENCES "shops" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "media_uploads_purpose_check" CHECK ((purpose)::text = ANY ((ARRAY['product_image'::character varying, 'content_image'::character varying])::text[])), CONSTRAINT "media_uploads_size_check" CHECK (size_bytes > 0));
-- create index "mediaupload_shop_id_id" to table: "media_uploads"
CREATE INDEX "mediaupload_shop_id_id" ON "media_uploads" ("shop_id", "id");
-- create "product_images" table
CREATE TABLE "product_images" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "image_key" character varying(255) NOT NULL, "position" integer NOT NULL DEFAULT 0, "alt" character varying(300) NOT NULL DEFAULT '', "width" integer NOT NULL, "height" integer NOT NULL, "created_at" timestamptz NOT NULL, "product_id" bigint NOT NULL, "shop_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "product_images_products_images" FOREIGN KEY ("product_id") REFERENCES "products" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "product_images_shops_shop" FOREIGN KEY ("shop_id") REFERENCES "shops" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "product_images_position_check" CHECK ("position" >= 0));
-- create index "product_images_image_key_key" to table: "product_images"
CREATE UNIQUE INDEX "product_images_image_key_key" ON "product_images" ("image_key");
-- create index "productimage_product_id_position_id" to table: "product_images"
CREATE INDEX "productimage_product_id_position_id" ON "product_images" ("product_id", "position", "id");
